var ITEMS=[["What masons do","Masons build with brick, block, and stone: walls, chimneys, fireplaces, patios, and foundations. It is physical, precise work \u2014 a wall out of plumb stays out of plumb forever. Apprenticeships run 3-4 years."], ["Essential tools","Brick trowel, pointing trowel, level, mason's line and blocks, story pole, brick hammer, 4-inch grinder with diamond blade, mortar mixer or hoe and box, and a stiff brush. Pros add: wet saw and scaffolding."], ["Key skills","Spreading mortar with the trowel, buttering bricks, keeping courses level and plumb, cutting brick cleanly, striking joints neatly, and reading the bond pattern. Speed comes from rhythm: the trowel hand never stops."], ["Safety essentials","Silica dust from cutting is a serious lung hazard \u2014 wet cut or respirators. Lift with legs; block is brutal. Scaffolding rules: guardrails and proper planking. Mortar burns skin; gloves and washing."], ["Getting started","Start as a tender (mixing mortar, carrying block) and learn by watching. Apprenticeships through unions or ABC. Bricklaying speed is the career metric \u2014 practice the trowel work daily."], ["Pro tips","Keep mortar workable, not wet. Tool joints at thumbprint-hard, not before. Cover fresh work from rain and sun. A story pole keeps courses honest. Clean smears immediately \u2014 dried mortar stains forever."], ["Mortar","Trade term \u2014 Mortar: The cement-lime-sand mix bonding masonry units."], ["Course","Trade term \u2014 Course: One horizontal row of masonry."], ["Wythe","Trade term \u2014 Wythe: One vertical layer of a wall."], ["Header","Trade term \u2014 Header: A brick laid with its end showing."], ["Stretcher","Trade term \u2014 Stretcher: A brick laid with its long face showing."], ["Running bond","Trade term \u2014 Running bond: The standard offset brick pattern."], ["Joint","Trade term \u2014 Joint: The mortar between units."], ["Tooling","Trade term \u2014 Tooling: Shaping the joint for weather and looks."], ["Weep hole","Trade term \u2014 Weep hole: Drainage gap at the wall base."], ["Flashing","Trade term \u2014 Flashing: Metal directing water out of the wall."], ["Lintel","Trade term \u2014 Lintel: The support over openings."], ["CMU","Trade term \u2014 CMU: Concrete masonry unit; cinder block."], ["Rebar","Trade term \u2014 Rebar: Steel reinforcement in masonry."], ["Grout","Trade term \u2014 Grout: Fluid concrete filling block cores."], ["Efflorescence","Trade term \u2014 Efflorescence: White salt deposits on masonry surfaces."], ["Tuckpointing","Trade term \u2014 Tuckpointing: Repairing mortar joints."], ["Story pole","Trade term \u2014 Story pole: A marked board for consistent course heights."], ["Bat","Trade term \u2014 Bat: A half brick."], ["Quoin","Trade term \u2014 Quoin: Decorative corner stones."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
